\begin{defn}
A \emph{Dedekind algebra} is a set $A$ together with a function $f
\colon A \to A$ and some $o \in A$  such that:
	\begin{enumerate}
		\item \ollabel{ded:proper} $o \notin \ran{f}$
		\item \ollabel{ded:injection} $f$ is !!a{injection}
		\item \ollabel{ded:closure} $A = \closureofunder{f}{o}$
	\end{enumerate}
\end{defn}

\begin{defn}
\emph{جبر ديديكند} هو مجموعة $A$ مع دالة $f
\colon A \to A$ وعنصر ما $o \in A$ بحيث:
	\begin{enumerate}
		\item \ollabel{ded:proper} $o \notin \ran{f}$
		\item \ollabel{ded:injection} $f$ هي !!a{injection}
		\item \ollabel{ded:closure} $A = \closureofunder{f}{o}$
	\end{enumerate}
\end{defn}

يمكننا أيضًا إثبات العكس. وهذا مهم لأنه يبين أن طريقتينا في تعريف
الصيغ متكافئتان: فهما تعطيان النتائج نفسها. ويعني أيضًا أن بوسعنا
إثبات مبرهنات عن الصيغ باستعمال الاستقراء العادي على طول متتاليات
التكوين.

\begin{lem}
\ollabel{lem:fseq-init}
افترض أن $\tuple{!A_0,\dotsc,!A_n}$ متتالية تكوين لـ~$!A_n$، وأن
$k \leq n$. عندئذ تكون $\tuple{!A_0,\dotsc,!A_k}$ متتالية تكوين
لـ~$!A_k$.
\end{lem}
